#include "hip_api.h"
#include <cstdio>
int main(int argc,char**argv){try{hip_probe::Api a(7);a.Check(a.hipInit(0),"init");a.Check(a.hipSetDevice(0),"device");auto fn=reinterpret_cast<int(*)(int*,hip_probe::Handle,int,size_t)>(GetProcAddress(a.dll,"hipModuleOccupancyMaxActiveBlocksPerMultiprocessor"));if(!fn)throw std::runtime_error("occupancy API missing");for(int i=1;i<argc;i++){hip_probe::Handle m{};a.Check(a.hipModuleLoad(&m,argv[i]),"module");for(auto n:{"c32_wave1_prefix_b8d_w16","c32_wave1_chain_w16","c32_wave1_post_b8_w16","c32_wave1_up_b8_w16"}){hip_probe::Handle f{};a.Check(a.hipModuleGetFunction(&f,m,n),"fn");int blocks=-1;a.Check(fn(&blocks,f,32,0),"occupancy");printf("OCC module=%s kernel=%s threads=32 blocks_per_multiprocessor=%d\n",argv[i],n,blocks);}a.Check(a.hipModuleUnload(m),"unload");}return 0;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
